<script lang="ts">
  import { t as uiText } from './i18n.js';
  import type {LayoutNode} from './types.js';
  interface Props {node:LayoutNode;fields?:{path:string;label:string}[];classes?:string[];onchange:(key:string,value:unknown)=>void}
  let {node,fields=[],classes=[],onchange}:Props=$props();
  let className=$state(''),classField=$state(''),styleName=$state(''),styleTemplate=$state('');
  function setMap(key:"classIf"|"bindStyle",name:string,value:string){const next:Record<string,string|number>={...node[key]};if(value==='')delete next[name];else next[name]=value;onchange(key,next);}
</script>
<label>{$uiText("Chỉ hiện khi trường có giá trị")}<select aria-label={$uiText("Điều kiện hiển thị")} value={node.visibleIf??''} onchange={(e)=>onchange('visibleIf',e.currentTarget.value)}><option value="">{$uiText("Luôn hiển thị")}</option>{#each fields as f}<option value={'$'+f.path}>{f.label}</option>{/each}{#if node.visibleIf&&!fields.some(f=>'$'+f.path===node.visibleIf)}<option value={node.visibleIf}>{node.visibleIf}</option>{/if}</select></label>
<strong class="rules-title">{$uiText("Đổi lớp CSS theo dữ liệu")}</strong>
{#each Object.entries(node.classIf??{}) as [name,binding]}<div class="rule"><code>{name}</code><span>{binding}</span><button aria-label={$uiText("Xóa điều kiện lớp {0}", name)} onclick={()=>setMap('classIf',name,'')}>{$uiText("×")}</button></div>{/each}
<label>{$uiText("Tên lớp CSS")}<input list="condition-css-classes" placeholder={$uiText("Chọn lớp có sẵn hoặc nhập tên")} bind:value={className} /></label><datalist id="condition-css-classes">{#each classes as name}<option value={name}></option>{/each}</datalist><label>{$uiText("Trường điều kiện")}<select bind:value={classField}><option value="">{$uiText("Chọn trường…")}</option>{#each fields as f}<option value={'$'+f.path}>{f.label}</option>{/each}</select></label><button disabled={!/^[a-zA-Z_][\w-]*$/.test(className.trim())||!classField} onclick={()=>{setMap('classIf',className.trim(),classField);className='';}}>{$uiText("＋ Thêm điều kiện lớp")}</button>
<strong class="rules-title">{$uiText("Thuộc tính hình thức lấy từ dữ liệu")}</strong>
{#each Object.entries(node.bindStyle??{}) as [name,template]}<label>{name}<div class="rule"><input aria-label={$uiText("Style động {0}", name)} value={template} onchange={(e)=>setMap('bindStyle',name,e.currentTarget.value)} /><button aria-label={$uiText("Xóa style động {0}", name)} onclick={()=>setMap('bindStyle',name,'')}>{$uiText("×")}</button></div></label>{/each}
<label>{$uiText("Thuộc tính CSS")}<input list="binding-css-properties" placeholder="background-color, color, width…" bind:value={styleName} /></label><datalist id="binding-css-properties"><option value="background-color"></option><option value="background-image"></option><option value="color"></option><option value="width"></option><option value="height"></option><option value="opacity"></option></datalist><label>{$uiText("Giá trị động")}<input placeholder={$uiText("Ví dụ: {color}, {progress}%")} bind:value={styleTemplate} /></label><button disabled={!styleName.trim()||!styleTemplate.trim()} onclick={()=>{setMap('bindStyle',styleName.trim(),styleTemplate);styleName='';styleTemplate='';}}>{$uiText("＋ Thêm style động")}</button>
<p class="hint">{$uiText("Điều kiện dùng giá trị boolean hoặc giá trị có/không. Style động dùng dấu ngoặc nhọn để chèn trường; Lua vẫn là nơi tính toán dữ liệu thật.")}</p>
<style>.rules-title{display:block;margin:16px 0 7px;font-size:11px;color:#abd0f5}.rule{display:flex;gap:5px;align-items:center;font-size:10px;margin:6px 0}.rule>span{flex:1;overflow-wrap:anywhere;color:#8ca9ce}.rule>input{flex:1;min-width:0;font-size:11px}.rule button{padding:3px 7px}.hint{font-size:10px;line-height:1.5;color:#8da2bc}button{font-size:10px}</style>
